keywordsList: [{ word: "appropriate", translation: "mos, to'g'ri, muvofiq" }, { word: "avoid", translation: "yaqinlashmaslik, chetda turmoq" }, { word: "behave", translation: "o'zini tutmoq, odob saqlamoq" }, { word: "calm", translation: "xotirjam" }, { word: "concern", translation: "tashvish, g'am" }, { word: "content", translation: "xursand, shod" }, { word: "expect", translation: "umid qilmoq, ishonmoq, kutmoq" }, { word: "frequently", translation: "tez-tez" }, { word: "habit", translation: "odat" }, { word: "instruct", translation: "ta'lim bermoq; ko'rsatma bermoq" }, { word: "issue", translation: "masala, muammo" }, { word: "none", translation: "hech qancha" }, { word: "patient", translation: "sabrli, toqatli" }, { word: "positive", translation: "ijobiy, porloq" }, { word: "punish", translation: "jazolamoq" }, { word: "represent", translation: "vakil bo'lmoq, vakillik qilmoq" }, { word: "shake", translation: "silkitmoq, siltamoq; silkinmoq" }, { word: "spread", translation: "tarqalmoq; surkamoq, surtmoq" }, { word: "stroll", translation: "sayr qilmoq, aylanib kelmoq" }, { word: "village", translation: "qishloq, ovul" }],
            testUrl: "https://slike7236-hash.github.io/universal-quiz-server/?lesson=ess1_4",
