    keywordsList: [{ word: "appreciate", translation: "qadrlamoq; ma'nosini tushunmoq" }, { word: "available", translation: "mavjud, bor, bo'sh" }, { word: "beat", translation: "yengmoq, yengib chiqmoq" }, { word: "bright", translation: "yorqin" }, { word: "celebrate", translation: "nishonlamoq" }, { word: "determine", translation: "tanlamoq, qaror qilmoq" }, { word: "disappear", translation: "ko'rinmay ketmoq; nari ketmoq" }, { word: "else", translation: "boshqa, o'zga" }, { word: "fair", translation: "xolis, adolatli, halol" }, { word: "flow", translation: "oqmoq" }, { word: "forward", translation: "oldinga" }, { word: "hill", translation: "tepalik, balandlik" }, { word: "level", translation: "daraja" }, { word: "lone", translation: "yakka, yolg'iz" }, { word: "puddle", translation: "ko'lmak" }, { word: "response", translation: "javob" }, { word: "season", translation: "fasl, mavsum" }, { word: "solution", translation: "yechim, javob" }, { word: "waste", translation: "behuda sovurmoq" }, { word: "whether", translation: "-mi; yo bo'lmasa" }],
    testUrl: "https://slike7236-hash.github.io/universal-quiz-server/?lesson=ess1_17",
