    keywordsList: [{ word: "advertise", translation: "reklama qilmoq" }, { word: "assign", translation: "tayinlamoq, topshirmoq" }, { word: "audience", translation: "auditoriya" }, { word: "breakfast", translation: "nonushta" }, { word: "competition", translation: "musobaqa" }, { word: "cool", translation: "salqin, jindak sovuq" }, { word: "gain", translation: "olmoq, oshirmoq" }, { word: "importance", translation: "ahamiyat" }, { word: "knowledge", translation: "bilim" }, { word: "major", translation: "muhim, katta" }, { word: "mean", translation: "baxil, ziqna" }, { word: "prefer", translation: "ma'qul ko'rmoq" }, { word: "president", translation: "prezident" }, { word: "progress", translation: "siljish, o'sish" }, { word: "respect", translation: "hurmat" }, { word: "rich", translation: "boy, badavlat" }, { word: "skill", translation: "mahorat, qobiliyat" }, { word: "somehow", translation: "bir amallab" }, { word: "strength", translation: "kuch, quvvat" }, { word: "vote", translation: "ovoz bermoq" }],
    testUrl: "https://slike7236-hash.github.io/universal-quiz-server/?lesson=ess1_29",
