    keywordsList: [{ word: "above", translation: "tepasida" }, { word: "ahead", translation: "old tarafida" }, { word: "amount", translation: "miqdor" }, { word: "belief", translation: "ishonch" }, { word: "center", translation: "markaz" }, { word: "common", translation: "odatliy" }, { word: "cost", translation: "narx turmoq" }, { word: "demonstrate", translation: "ko'rsatmoq" }, { word: "different", translation: "turlicha, o'zgacha" }, { word: "evidence", translation: "dalil, isbot" }, { word: "honesty", translation: "odillik, oqillik" }, { word: "idiom", translation: "idioma" }, { word: "independent", translation: "mustaqil" }, { word: "inside", translation: "ichki qism" }, { word: "master", translation: "master, usta" }, { word: "memory", translation: "xotira; yod" }, { word: "proper", translation: "odobdan, o'rinli" }, { word: "scan", translation: "qarab chiqmoq" }, { word: "section", translation: "qism, bo'lim" }, { word: "surface", translation: "yuza, sirt" }],
    testUrl: "https://slike7236-hash.github.io/universal-quiz-server/?lesson=ess1_30",
    games: { matchup: "...", anagrama: "...", typeanswer: "...", wordsearch: "...", pair: "..." }
