      keywordsList: [{ word: "bath", translation: "vanna, cho'milish" }, { word: "bend", translation: "bukmoq, egmoq" }, { word: "chew", translation: "chaynamoq" }, { word: "disabled", translation: "nogiron, imkoniyati cheklangan" }, { word: "fantastic", translation: "ajoyib, fantastik" }, { word: "fiction", translation: "badiiy adabiyot, uydirma" }, { word: "flag", translation: "bayroq" }, { word: "inspect", translation: "tekshirmoq, ko'zdan kechirmoq" }, { word: "journal", translation: "jurnal" }, { word: "liquid", translation: "suyuqlik" }, { word: "marvel", translation: "hayratda qolmoq, zavqlanmoq" }, { word: "nutrient", translation: "oziq modda" }, { word: "overcome", translation: "yengib o'tmoq, enmoq" }, { word: "recall", translation: "eslamoq, xotirlamoq" }, { word: "regret", translation: "afsuslanmoq, afsus chekmoq" }, { word: "soul", translation: "ruh, qalb" }, { word: "sufficient", translation: "yetarli, yetarlicha" }, { word: "surgery", translation: "operatsiya, jarrohlik amaliyoti" }, { word: "tough", translation: "qiyin, og'ir, qattiq" }, { word: "tube", translation: "truba, naycha" }],
