      keywordsList: [{ word: "beak", translation: "клюв" }, { word: "damp", translation: "сырой, влажный" }, { word: "disapprove", translation: "не одобрять" }, { word: "except", translation: "кроме, за исключением" }, { word: "flight", translation: "полет" }, { word: "fond", translation: "любящий, испытывающий нежность" }, { word: "immoral", translation: "аморальный, неадекватный" }, { word: "ivy", translation: "плющ" }, { word: "moan", translation: "стонать" }, { word: "oblivious", translation: "забывчивый, не обращающий внимания" }, { word: "perish", translation: "погибать" }, { word: "pit", translation: "яма" }, { word: "rim", translation: "край, ободок" }, { word: "roost", translation: "насест, приютить" }, { word: "slippery", translation: "скользкий" }, { word: "soar", translation: "парить, взмывать" }, { word: "trivial", translation: "тривиальный, незначительный" }, { word: "typical", translation: "типичный, характерный" }, { word: "utterly", translation: "совершенно, абсолютно" }, { word: "weep", translation: "плакать" }],
