      keywordsList: [{ word: "awhile", translation: "biroz vaqt, bir oz" }, { word: "cyberspace", translation: "kiberfazo, virtual olam" }, { word: "edit", translation: "tahrirlamoq, tuzatmoq" }, { word: "essay", translation: "insho, esse" }, { word: "evaluate", translation: "baholamoq, o'rganib chiqmoq" }, { word: "faint", translation: "hushidan ketmoq" }, { word: "global", translation: "dunyoviy, global" }, { word: "gymnasium", translation: "sport zali" }, { word: "highlight", translation: "bo'rttirib/ajratib ko'rsatmoq" }, { word: "ignorant", translation: "bexabar, bilimsiz" }, { word: "index", translation: "ko'rsatkich, indeks" }, { word: "lecture", translation: "ma'ruza" }, { word: "moral", translation: "xulosa, axloqiy saboq" }, { word: "operate", translation: "ishlamoq, faoliyat ko'rsatmoq" }, { word: "private", translation: "shaxsiy, xususiy" }, { word: "recent", translation: "yaqindagi, oxirgi" }, { word: "resolution", translation: "qaror, ahd" }, { word: "semester", translation: "semestr" }, { word: "typewritten", translation: "mashinkada/kompyuterda yozilgan" }, { word: "weird", translation: "g'alati, ajablanarli" }],
