      keywordsList: [{ word: "alongside", translation: "yonida, birga" }, { word: "appetite", translation: "ishtaha" }, { word: "assist", translation: "yordam bermoq, ko'maklashmoq" }, { word: "breeze", translation: "shabada, muloyim shamol" }, { word: "defy", translation: "qarshi chiqmoq, bo'ysunmaslik" }, { word: "display", translation: "ko'rsatmoq, namoyish etmoq" }, { word: "efficient", translation: "samarali, mahsuldor" }, { word: "feeble", translation: "nimjon, kuchsiz" }, { word: "forgive", translation: "kechirmoq" }, { word: "lively", translation: "shaddod, jonli, g'ayratli" }, { word: "majestic", translation: "muhtasham, salobatli" }, { word: "nor", translation: "ham emas, na ... na" }, { word: "outraged", translation: "g'azablangan, darg'azab" }, { word: "pessimistic", translation: "pessimist, tushkun" }, { word: "rumor", translation: "mish-mish, xabar" }, { word: "slap", translation: "shapaloq urmoq" }, { word: "smash", translation: "urib sindirmoq, parchalab tashlamoq" }, { word: "subject", translation: "fan, mavzu" }, { word: "wage", translation: "ish haqi, maosh" }, { word: "whereas", translation: "holbuki, vaholanki" }],
