      keywordsList: [{ word: "betray", translation: "xiyonat qilmoq" }, { word: "blast", translation: "kuchli portlash ovozi" }, { word: "bracelet", translation: "bilakuzuk" }, { word: "cease", translation: "to'xtatmoq, bas qilmoq" }, { word: "choke", translation: "bo'g'ilmoq" }, { word: "civil", translation: "fuqarolik, ichki" }, { word: "comment", translation: "izoh bermoq, fikr bildirmoq" }, { word: "cross", translation: "kesib o'tmoq" }, { word: "dent", translation: "tish (urilib kirgan joy)" }, { word: "distrust", translation: "ishonmaslik" }, { word: "fort", translation: "qal’a, qo'rg'on" }, { word: "found", translation: "asos solmoq" }, { word: "lining", translation: "astar" }, { word: "mass", translation: "massa, to'da" }, { word: "pray", translation: "duo qilmoq, iltijo qilmoq" }, { word: "rife", translation: "to'la, keng tarqalgan" }, { word: "sole", translation: "yagona, asosiy" }, { word: "sweep", translation: "supurmoq" }, { word: "treachery", translation: "xiyonat" }, { word: "tuck", translation: "tiqib qo'ymoq" }],
