      keywordsList: [{ word: "aircraft", translation: "летательный аппарат, самолет" }, { word: "celebrity", translation: "знаменитость, звезда" }, { word: "concrete", translation: "бетон" }, { word: "decisive", translation: "решительный" }, { word: "esteemed", translation: "уважаемый, почитаемый" }, { word: "ethical", translation: "этичный" }, { word: "extinct", translation: "вымерший" }, { word: "hardy", translation: "выносливый, крепкий" }, { word: "institute", translation: "институт, учреждение" }, { word: "jealousy", translation: "зависть, ревность" }, { word: "migrate", translation: "мигрировать" }, { word: "nurture", translation: "воспитывать, лелеять" }, { word: "overhead", translation: "над головой, вверху" }, { word: "principle", translation: "принцип" }, { word: "rural", translation: "сельский, деревенский" }, { word: "secluded", translation: "уединенный" }, { word: "species", translation: "вид (биол.)" }, { word: "swamp", translation: "болото" }, { word: "traverse", translation: "пересекать" }, { word: "zoology", translation: "зоология" }],
